<script setup>
import {reactive,ref} from 'vue';import Dialog from './Dialog.vue';import Icon from './Icon.vue';import {useWorkspace} from '../stores/workspace.js';import {statuses,modes,customers} from '../data/seed.js';
const props=defineProps({shipment:Object});const emit=defineEmits(['close']);const store=useWorkspace();const errors=ref({});const form=reactive({...props.shipment||{customer:'',origin:'',destination:'',originCountry:'',destinationCountry:'',mode:'Ocean',status:'Booked',eta:'',weight:'',value:'',description:'',reference:''}});
function submit(){const result=store.save(form,props.shipment?.id);errors.value=result.errors||{};if(result.ok)emit('close');}
</script>
<template><Dialog :title="shipment?'Edit shipment':'Create a shipment'" wide @close="emit('close')"><p class="form-intro">Keep every detail in one place. Fields marked * are required.</p><form @submit.prevent="submit" novalidate><div class="form-grid"><label class="full">Customer *<input v-model="form.customer" list="customer-list" maxlength="200" :aria-invalid="!!errors.customer" placeholder="Select or enter a customer"><datalist id="customer-list"><option v-for="c in customers" :value="c"/></datalist><small class="field-error" v-if="errors.customer">{{errors.customer}}</small></label><label>Origin city *<input v-model="form.origin" maxlength="200" placeholder="e.g. Shanghai" :aria-invalid="!!errors.origin"><small v-if="errors.origin" class="field-error">{{errors.origin}}</small></label><label>Destination city *<input v-model="form.destination" maxlength="200" placeholder="e.g. Rotterdam" :aria-invalid="!!errors.destination"><small v-if="errors.destination" class="field-error">{{errors.destination}}</small></label><label>Origin country<input v-model="form.originCountry" maxlength="100" placeholder="e.g. China"></label><label>Destination country<input v-model="form.destinationCountry" maxlength="100" placeholder="e.g. Netherlands"></label><label>Transport mode *<select v-model="form.mode"><option v-for="m in modes">{{m}}</option></select></label><label>Status *<select v-model="form.status"><option v-for="s in statuses">{{s}}</option></select></label><label>Expected arrival *<input v-model="form.eta" type="date" :aria-invalid="!!errors.eta"><small v-if="errors.eta" class="field-error">{{errors.eta}}</small></label><label>Reference<input v-model="form.reference" maxlength="200" placeholder="PO-2026-001"></label><label>Total weight (kg) *<input v-model="form.weight" type="number" min="0.01" step="0.01" :aria-invalid="!!errors.weight" placeholder="0"><small v-if="errors.weight" class="field-error">{{errors.weight}}</small></label><label>Shipment value (€) *<input v-model="form.value" type="number" min="0" step="0.01" :aria-invalid="!!errors.value" placeholder="0"><small v-if="errors.value" class="field-error">{{errors.value}}</small></label><label class="full">Goods description *<textarea v-model="form.description" maxlength="200" :aria-invalid="!!errors.description" placeholder="What are you shipping?"></textarea><small v-if="errors.description" class="field-error">{{errors.description}}</small></label></div><p v-if="Object.keys(errors).length" class="field-error" role="alert">{{errors.form||'Please check the highlighted fields.'}}</p><div class="dialog-actions"><button type="button" class="btn" @click="emit('close')">Cancel</button><button class="btn primary" type="submit"><Icon name="Check"/>{{shipment?'Save changes':'Create shipment'}}</button></div></form></Dialog></template>
